    SELECT TL_SCLOGX_SEQ.NEXTVAL
      FROM DUAL

INSERT /* setSchedulerLog */
       INTO TL_SCLOGX (
            RUNX_NUMB
          , SCHD_CODE
          , METH_NAME
          , EXEC_STAT
          , STRT_DATE
          , TRGT_CNTT
          , SUCC_CNTT
          , FAIL_CNTT
) VALUES (  #{runxNumb}
          , #{schdCode}
          , #{methName}
          , #{execStat}
          , SYSTIMESTAMP
          , #{trgtCntt}
          , #{succCntt}
          , #{failCntt}
)

mapper.update:
UPDATE /* uptSchedulerLog */
       TL_SCLOGX
   SET EXEC_STAT = #{execStat}
     , FNSH_DATE = SYSTIMESTAMP
     , TRGT_CNTT = #{trgtCntt}
     , SUCC_CNTT = #{succCntt}
     , FAIL_CNTT = #{failCntt}
     , EXEC_MSEC = #{execMsec}
 WHERE RUNX_NUMB = #{runxNumb}

mapper.insert:


/* setSchedulerFail */
INSERT INTO TL_SCFAIL (
            RUNX_NUMB
          , FAIL_NUMB
          , FAIL_TYPE
          , RSLT_CODE
          , RSLT_MESG
          , ERRO_TYPE
          , ERRO_CNTN
          , FAIL_DATE
)
SELECT #{runxNumb}
     , NVL(MAX(FAIL.FAIL_NUMB), #{numberZero}) + #{numberOne}
     , #{failType}
     , #{rsltCode, jdbcType=NUMERIC}
     , #{rsltMesg, jdbcType=VARCHAR}
     , #{erroType, jdbcType=VARCHAR}
     , #{erroCntn, jdbcType=VARCHAR}
     , SYSTIMESTAMP
  FROM TL_SCFAIL FAIL
 WHERE FAIL.RUNX_NUMB = #{runxNumb}
